package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class AgentBRT_Lang_26_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Set up a FastDateFormat with a specific locale and timezone
        Locale locale = Locale.JAPAN; // Japanese locale
        TimeZone timeZone = TimeZone.getTimeZone("Asia/Tokyo");
        FastDateFormat fastDateFormat = FastDateFormat.getInstance("MMMM", timeZone, locale);

        // Date to format
        Date date = new Date(0); // January 1, 1970

        // Expected output in Japanese locale
        String expected = "1月"; // January in Japanese

        // Format the date
        String actual = fastDateFormat.format(date);

        // Assert that the formatted date matches the expected output
        assertEquals("The formatted date should match the expected month name in Japanese.", expected, actual);
    }
}

