package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;

public class AgentBRT_Lang_26_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Set up a FastDateFormat with a specific locale and timezone
        Locale locale = Locale.FRANCE; // French locale
        TimeZone timeZone = TimeZone.getTimeZone("Europe/Paris");
        FastDateFormat fastDateFormat = FastDateFormat.getInstance("EEEE, MMMM d, yyyy", timeZone, locale);

        // Date to format
        Date date = new Date(0); // January 1, 1970

        // Expected output in French locale
        String expected = "jeudi, janvier 1, 1970"; // Thursday, January 1, 1970 in French

        // Format the date
        String actual = fastDateFormat.format(date);

        // Assert that the formatted date matches the expected output
        assertEquals("The formatted date should match the expected full date in French.", expected, actual);
    }
}

